<script setup>
import { computed } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { merchants, products } from '../data'; import { ArrowLeft, Clock, MapPin, Plus } from 'lucide-vue-next'; const route=useRoute(),router=useRouter(); const merchant=computed(()=>merchants.find(m=>m.id===Number(route.params.id))); const list=computed(()=>products.filter(p=>p.merchantId===Number(route.params.id)))
</script>
<template><button class="back-btn" @click="router.back()"><ArrowLeft :size="17"/>返回</button><section v-if="merchant" class="merchant-hero"><div class="merchant-symbol" :style="{background:merchant.color}">{{merchant.emoji}}</div><div><span class="pill green">{{merchant.tag}}</span><h2>{{merchant.name}}</h2><p>{{merchant.desc}}</p><div class="merchant-info"><span>★ {{merchant.rating}} 评分</span><span><Clock :size="15"/> {{merchant.time}}</span><span><MapPin :size="15"/> 距离 0.8 km</span></div></div></section><div class="section-head compact"><div><span class="eyebrow">MENU</span><h3>今日菜单</h3></div></div><div class="merchant-menu"><div v-for="p in list" :key="p.id" class="menu-row"><div class="menu-thumb">{{p.emoji}}</div><div class="menu-main"><h3>{{p.name}}</h3><p>{{p.desc}}</p><span class="nutrition-line">{{p.nutrition}}</span></div><div class="menu-action"><b>¥{{p.price}}</b><button class="icon-btn"><Plus :size="18"/></button></div></div></div></template>
